"""Views for the accounts app."""

from django.http import JsonResponse
from django.shortcuts import get_object_or_404

from .models import Account


def delete_account(request, pk):
    """Delete the account. Comments and addresses go with it."""
    account = get_object_or_404(Account, pk=pk)
    account.delete()
    return JsonResponse({"deleted": True})


def profile(request, pk):
    account = get_object_or_404(Account, pk=pk)
    return JsonResponse({"email": account.email, "full_name": account.full_name})

"""Small string helpers. No personal data passes through this module."""


def slugify(value):
    return "-".join(part for part in value.lower().split() if part)


def truncate(value, limit=80):
    if len(value) <= limit:
        return value
    return value[: limit - 3] + "..."


def humanise_bytes(count):
    for unit in ("B", "KB", "MB"):
        if count < 1024:
            return f"{count} {unit}"
        count //= 1024
    return f"{count} GB"
